const d = $json;

const knownFields = new Set([
  "caseNum",
  "birthDate",
  "admissionDate",
  "room",
  "weight",
  "height",
  "isPregnancy",
  "isGyne",
  "isPostpartum",
  "obscoreG",
  "obscoreP",
  "obscoreFT",
  "obscorePr",
  "obscoreAb",
  "obscoreLB",
  "gynecologicalDiagnosis",
  "unresolvedDiagnoses",
  "ignoredDiagnosisTerms",
  "classificationEvidence",
  "source",
  "validation",
  "runContext"
]);

const unknownFields = Object.keys(d)
  .filter(key => !knownFields.has(key));

const mappedDiagnoses =
  d.gynecologicalDiagnosis ?? [];

const unresolvedDiagnoses =
  d.unresolvedDiagnoses ?? [];

const ignoredDiagnosisTerms =
  d.ignoredDiagnosisTerms ?? [];

const recognizedTerms =
  mappedDiagnoses.length +
  unresolvedDiagnoses.length +
  ignoredDiagnosisTerms.length;

const mappedTerms =
  mappedDiagnoses.length;

const unresolvedTerms =
  unresolvedDiagnoses.length;

const ignoredTerms =
  ignoredDiagnosisTerms.length;

const mappingComplete =
  unresolvedTerms === 0;

const needsClinicalMappingReview =
  unresolvedTerms > 0;

const ruleEvaluation = [];

// Gyne diagnosis rules
if (d.isGyne === true) {
  ruleEvaluation.push({
    field: "gynecologicalDiagnosis",
    visible: true,
    required: true,
    applicable: true,
    reason: "isGyne = true",
    satisfied: mappedDiagnoses.length > 0
  });
} else if (d.isGyne === false) {
  ruleEvaluation.push({
    field: "gynecologicalDiagnosis",
    visible: false,
    required: false,
    applicable: false,
    reason: "isGyne = false",
    satisfied: true
  });
} else {
  ruleEvaluation.push({
    field: "gynecologicalDiagnosis",
    visible: null,
    required: null,
    applicable: null,
    reason: "isGyne is not classified",
    satisfied: false
  });
}

// Pregnancy section
if (d.isPregnancy === true) {
  ruleEvaluation.push({
    field: "pregnancySection",
    visible: true,
    required: true,
    applicable: true,
    reason: "isPregnancy = true",
    satisfied: null
  });
} else if (d.isPregnancy === false) {
  ruleEvaluation.push({
    field: "pregnancySection",
    visible: false,
    required: false,
    applicable: false,
    reason: "isPregnancy = false",
    satisfied: true
  });
} else {
  ruleEvaluation.push({
    field: "pregnancySection",
    visible: null,
    required: null,
    applicable: null,
    reason: "isPregnancy is not classified",
    satisfied: false
  });
}

// Postpartum section
if (d.isPostpartum === true) {
  ruleEvaluation.push({
    field: "postpartumSection",
    visible: true,
    required: null,
    applicable: true,
    reason: "isPostpartum = true",
    satisfied: null
  });
} else if (d.isPostpartum === false) {
  ruleEvaluation.push({
    field: "postpartumSection",
    visible: false,
    required: false,
    applicable: false,
    reason: "isPostpartum = false",
    satisfied: true
  });
} else {
  ruleEvaluation.push({
    field: "postpartumSection",
    visible: null,
    required: null,
    applicable: null,
    reason: "isPostpartum is not classified",
    satisfied: false
  });
}

// OB score applicability
const obScoreValues = [
  d.obscoreG,
  d.obscoreP,
  d.obscoreFT,
  d.obscorePr,
  d.obscoreAb,
  d.obscoreLB
];

const hasAnyOBScore =
  obScoreValues.some(
    value => value !== null && value !== undefined
  );

ruleEvaluation.push({
  field: "obstetricScore",
  visible: null,
  required: null,
  applicable: hasAnyOBScore,
  reason: hasAnyOBScore
    ? "OB score data was extracted from source"
    : "No OB score data was extracted",
  satisfied: hasAnyOBScore
});

// Weight extraction
ruleEvaluation.push({
  field: "weight",
  visible: true,
  required: false,
  applicable: true,
  reason: "General patient measurement",
  satisfied:
    d.weight !== null &&
    d.weight !== undefined
});

// Height extraction
ruleEvaluation.push({
  field: "height",
  visible: true,
  required: false,
  applicable: true,
  reason: "General patient measurement",
  satisfied:
    d.height !== null &&
    d.height !== undefined
});

const unsatisfiedRules =
  ruleEvaluation.filter(
    rule =>
      rule.required === true &&
      rule.satisfied === false
  );

const timestamp =
  new Date().toISOString();

// Generate a stable non-identifying knowledge ID.
// The same caseNum will always generate the same ID,
// so rerunning the same candidate overwrites its knowledge file.

if (!d.caseNum) {
  throw new Error("Cannot generate knowledgeId: candidate has no caseNum");
}

function stableHash(value) {
  const str = String(value);

  let hash1 = 0xdeadbeef;
  let hash2 = 0x41c6ce57;

  for (let i = 0; i < str.length; i++) {
    const ch = str.charCodeAt(i);

    hash1 = Math.imul(hash1 ^ ch, 2654435761);
    hash2 = Math.imul(hash2 ^ ch, 1597334677);
  }

  hash1 =
    Math.imul(
      hash1 ^ (hash1 >>> 16),
      2246822507
    ) ^
    Math.imul(
      hash2 ^ (hash2 >>> 13),
      3266489909
    );

  hash2 =
    Math.imul(
      hash2 ^ (hash2 >>> 16),
      2246822507
    ) ^
    Math.imul(
      hash1 ^ (hash1 >>> 13),
      3266489909
    );

  return (
    (hash2 >>> 0).toString(16).padStart(8, "0") +
    (hash1 >>> 0).toString(16).padStart(8, "0")
  );
}

const knowledgeId =
  `CASE-${stableHash(d.caseNum)}`;

return {
  json: {
    schemaVersion: 2,

    knowledgeId,
    timestamp,

    executionId:
      $execution?.id ?? null,

    classification: {
      isPregnancy:
        d.isPregnancy ?? null,

      isGyne:
        d.isGyne ?? null,

      isPostpartum:
        d.isPostpartum ?? null,

      evidence:
        d.classificationEvidence ?? []
    },

    runContext: {
      mode: d.runContext?.mode ?? "UNKNOWN",
      rawCaseId: d.runContext?.rawCaseId ?? null
    },

    extracted: {
      birthDatePresent:
        Boolean(d.birthDate),

      admissionDatePresent:
        Boolean(d.admissionDate),

      roomPresent:
        d.room !== null &&
        d.room !== undefined,

      weightPresent:
        d.weight !== null &&
        d.weight !== undefined,

      heightPresent:
        d.height !== null &&
        d.height !== undefined,

      obscoreG:
        d.obscoreG ?? null,

      obscoreP:
        d.obscoreP ?? null,

      obscoreFT:
        d.obscoreFT ?? null,

      obscorePr:
        d.obscorePr ?? null,

      obscoreAb:
        d.obscoreAb ?? null,

      obscoreLB:
        d.obscoreLB ?? null
    },

    mapped: {
      gynecologicalDiagnosis:
        mappedDiagnoses
    },

    unresolved:
      unresolvedDiagnoses,

    ignored:
      ignoredDiagnosisTerms,

    mappingCoverage: {
      recognizedTerms,
      mappedTerms,
      unresolvedTerms,
      ignoredTerms
    },

    mappingStatus: {
      mappingComplete,
      needsClinicalMappingReview
    },

    ruleEvaluation,

    ruleStatus: {
      evaluatedRules:
        ruleEvaluation.length,

      unsatisfiedRequiredRules:
        unsatisfiedRules,

      needsRuleReview:
        unsatisfiedRules.length > 0
    },

    validation: {
      readyForPOGS:
        d.validation?.readyForPOGS ?? false,

      issues:
        d.validation?.issues ?? [],

      warnings:
        d.validation?.warnings ?? []
    },

    discovery: {
      unknownTopLevelFields:
        unknownFields,

      needsMappingReview:
        needsClinicalMappingReview,

      needsRuleReview:
        unknownFields.length > 0 ||
        unsatisfiedRules.length > 0
    }
  }
};

const record =
  $json.currentRecord;

if (!record?.knowledgeId) {
  throw new Error(
    "Missing current knowledge record"
  );
}

const content =
  JSON.stringify(
    record,
    null,
    2
  );

return {
  json: {
    knowledgeId:
      record.knowledgeId,

    fileName:
      `${record.knowledgeId}.json`,

    regressionResult:
      $json.regressionResult
  },

  binary: {
    data: {
      data:
        Buffer
          .from(content, "utf8")
          .toString("base64"),

      mimeType:
        "application/json",

      fileName:
        `${record.knowledgeId}.json`
    }
  }
};

const items = $input.all();

const summary = {
  generatedAt: new Date().toISOString(),
  totalCases: items.length,

  statusCounts: {
    NEW: 0,
    IMPROVED: 0,
    REGRESSED: 0,
    CHANGED: 0,
    UNCHANGED: 0,
    UNKNOWN: 0
  },

  readyForPOGS: 0,
  notReadyForPOGS: 0,

  totalMappedTerms: 0,
  totalUnresolvedTerms: 0,
  totalValidationIssues: 0,
  totalWarnings: 0,
  totalUnsatisfiedRules: 0,
  totalUnknownFields: 0,

  needsAttention: 0,

  cases: []
};

for (const item of items) {
  const data = item.json;

  const regression =
    data.regressionResult ?? {};

  const current =
    data.currentRecord ?? {};

  const status =
    regression.status ?? "UNKNOWN";

  if (
    Object.prototype.hasOwnProperty.call(
      summary.statusCounts,
      status
    )
  ) {
    summary.statusCounts[status]++;
  } else {
    summary.statusCounts.UNKNOWN++;
  }

  const metrics =
    regression.currentMetrics ?? {};

  const ready =
    metrics.readyForPOGS === true;

  if (ready) {
    summary.readyForPOGS++;
  } else {
    summary.notReadyForPOGS++;
  }

  summary.totalMappedTerms +=
    Number(metrics.mapped ?? 0);

  summary.totalUnresolvedTerms +=
    Number(metrics.unresolved ?? 0);

  summary.totalValidationIssues +=
    Number(metrics.issues ?? 0);

  summary.totalWarnings +=
    Number(metrics.warnings ?? 0);

  summary.totalUnsatisfiedRules +=
    Number(metrics.unsatisfiedRules ?? 0);

  summary.totalUnknownFields +=
    Number(metrics.unknownFields ?? 0);

  const requiresAttention =
    status === "REGRESSED" ||
    status === "CHANGED" ||
    Number(metrics.unresolved ?? 0) > 0 ||
    Number(metrics.issues ?? 0) > 0 ||
    Number(metrics.unsatisfiedRules ?? 0) > 0 ||
    Number(metrics.unknownFields ?? 0) > 0;

  if (requiresAttention) {
    summary.needsAttention++;
  }

  summary.cases.push({
    knowledgeId:
      data.knowledgeId ?? null,

    rawCaseId:
      current.runContext?.rawCaseId ?? null,

    mode:
      current.runContext?.mode ?? "UNKNOWN",

    status,

    readyForPOGS: ready,

    mappedTerms:
      metrics.mapped ?? 0,

    unresolvedTerms:
      metrics.unresolved ?? 0,

    validationIssues:
      metrics.issues ?? 0,

    warnings:
      metrics.warnings ?? 0,

    unsatisfiedRules:
      metrics.unsatisfiedRules ?? 0,

    unknownFields:
      metrics.unknownFields ?? 0,

    changes:
      regression.changes ?? [],

    needsAttention:
      requiresAttention
  });
}

summary.allCasesStable =
  summary.statusCounts.REGRESSED === 0 &&
  summary.statusCounts.CHANGED === 0;

return [
  {
    json: summary
  }
];

const report = $json;

const filename = "latest-regression.json";

const content =
  JSON.stringify(report, null, 2);

return [{
  json: {
    filename
  },

  binary: {
    data: {
      data:
        Buffer
          .from(content, "utf8")
          .toString("base64"),

      mimeType:
        "application/json",

      fileName:
        filename
    }
  }
}];

const current = $json;

if (!current?.knowledgeId) {
  throw new Error(
    "Current knowledge record is missing knowledgeId"
  );
}


// --------------------------------------------------
// Load previous knowledge record if one exists
// --------------------------------------------------

let previous = null;

const binaryKeys =
  Object.keys($binary ?? {});

if (binaryKeys.length > 0) {

  try {

    const binaryProperty =
      binaryKeys[0];

    const buffer =
  await this.helpers.getBinaryDataBuffer(
    $itemIndex,
    binaryProperty
  );
    const text =
      buffer.toString("utf8");

    previous =
      JSON.parse(text);

  } catch (error) {

    previous = null;

  }
}


// --------------------------------------------------
// Normalize objects before comparing
// Ignore fields that naturally change every run
// --------------------------------------------------

function comparable(record) {

  if (!record) return null;

  const copy =
    JSON.parse(
      JSON.stringify(record)
    );

  delete copy.lastUpdatedAt;
  delete copy.timestamp;
  delete copy.executionId;
  delete copy.capturedAt;
  delete copy.runContext;
  return copy;
}


// --------------------------------------------------
// Useful numeric metrics
// --------------------------------------------------

function metrics(record) {

  return {

    mapped:
      record?.mappingCoverage
        ?.mappedTerms ?? 0,

    unresolved:
      record?.mappingCoverage
        ?.unresolvedTerms ?? 0,

    issues:
      record?.validation
        ?.issues?.length ?? 0,

    warnings:
      record?.validation
        ?.warnings?.length ?? 0,

    unsatisfiedRules:
      record?.ruleStatus
        ?.unsatisfiedRequiredRules
        ?.length ?? 0,

    unknownFields:
      record?.discovery
        ?.unknownTopLevelFields
        ?.length ?? 0,

    readyForPOGS:
      record?.validation
        ?.readyForPOGS ?? false

  };
}


const currentMetrics =
  metrics(current);

const previousMetrics =
  previous
    ? metrics(previous)
    : null;


// --------------------------------------------------
// Determine change status
// --------------------------------------------------

let status = "NEW";

if (previous) {

  const same =
    JSON.stringify(
      comparable(previous)
    ) ===
    JSON.stringify(
      comparable(current)
    );

  if (same) {

    status = "UNCHANGED";

  } else {

    let improvementScore = 0;
    let regressionScore = 0;


    // Fewer unresolved mappings = improvement
    if (
      currentMetrics.unresolved <
      previousMetrics.unresolved
    ) {
      improvementScore++;
    }

    if (
      currentMetrics.unresolved >
      previousMetrics.unresolved
    ) {
      regressionScore++;
    }


    // More mapped terms = improvement
    if (
      currentMetrics.mapped >
      previousMetrics.mapped
    ) {
      improvementScore++;
    }

    if (
      currentMetrics.mapped <
      previousMetrics.mapped
    ) {
      regressionScore++;
    }


    // Fewer validation issues = improvement
    if (
      currentMetrics.issues <
      previousMetrics.issues
    ) {
      improvementScore++;
    }

    if (
      currentMetrics.issues >
      previousMetrics.issues
    ) {
      regressionScore++;
    }


    // Fewer unsatisfied rules = improvement
    if (
      currentMetrics.unsatisfiedRules <
      previousMetrics.unsatisfiedRules
    ) {
      improvementScore++;
    }

    if (
      currentMetrics.unsatisfiedRules >
      previousMetrics.unsatisfiedRules
    ) {
      regressionScore++;
    }


    // Fewer unknown fields = improvement
    if (
      currentMetrics.unknownFields <
      previousMetrics.unknownFields
    ) {
      improvementScore++;
    }

    if (
      currentMetrics.unknownFields >
      previousMetrics.unknownFields
    ) {
      regressionScore++;
    }


    // Becoming POGS-ready is improvement
    if (
      currentMetrics.readyForPOGS === true &&
      previousMetrics.readyForPOGS === false
    ) {
      improvementScore++;
    }

    if (
      currentMetrics.readyForPOGS === false &&
      previousMetrics.readyForPOGS === true
    ) {
      regressionScore++;
    }


    if (
      improvementScore > 0 &&
      regressionScore === 0
    ) {

      status = "IMPROVED";

    } else if (
      regressionScore > 0 &&
      improvementScore === 0
    ) {

      status = "REGRESSED";

    } else {

      status = "CHANGED";

    }
  }
}


// --------------------------------------------------
// Build specific differences
// --------------------------------------------------

const changes = [];

if (previousMetrics) {

  for (
    const field of Object.keys(currentMetrics)
  ) {

    const before =
      previousMetrics[field];

    const after =
      currentMetrics[field];

    if (
      JSON.stringify(before) !==
      JSON.stringify(after)
    ) {

      changes.push({
        field,
        before,
        after
      });

    }
  }
}


return {
  json: {

    knowledgeId:
      current.knowledgeId,

    regressionResult: {

      status,

      hadPreviousRecord:
        Boolean(previous),

      previousMetrics,

      currentMetrics,

      changes

    },

    currentRecord:
      current

  }
};

// Regression Summary should provide exactly one item.
const summaryItems =
  $input.all();

if (summaryItems.length === 0) {
  throw new Error(
    "Regression Summary produced no output"
  );
}

const regression =
  summaryItems[0].json;


// --------------------------------------------------
// Get the exact knowledge records used in this
// regression run.
//
// Compare Knowledge Record already contains the
// current knowledge record for each case.
// --------------------------------------------------

const compareItems =
  $items(
    "Compare Knowledge Record"
  );

if (compareItems.length === 0) {
  throw new Error(
    "No Compare Knowledge Record items found"
  );
}


const knowledge = [];

for (const item of compareItems) {
  const record =
    item.json.currentRecord ??
    null;

  if (!record) {
    throw new Error(
      "Compare Knowledge Record item is missing currentRecord"
    );
  }

  if (!record.knowledgeId) {
    throw new Error(
      "Knowledge record is missing knowledgeId"
    );
  }

  const cleanRecord = {
    ...record
  };

  delete cleanRecord.mimeType;
  delete cleanRecord.fileType;
  delete cleanRecord.fileName;
  delete cleanRecord.fileExtension;
  delete cleanRecord.fileSize;

  knowledge.push(
    cleanRecord
  );
}


// --------------------------------------------------
// Deterministic ordering.
//
// This makes bundles easier to diff between runs.
// --------------------------------------------------

knowledge.sort(
  (a, b) =>
    String(a.knowledgeId)
      .localeCompare(
        String(b.knowledgeId)
      )
);


// --------------------------------------------------
// Use the regression timestamp as the run identity.
// --------------------------------------------------

const generatedAt =
  regression.generatedAt ??
  new Date().toISOString();

const regressionRunId =
  `REG-${generatedAt
    .replace(/[-:.]/g, "")
    .replace("T", "-")
    .replace("Z", "")}`;


// --------------------------------------------------
// Final evidence bundle.
//
// IMPORTANT:
// This contains sanitized knowledge records,
// not raw Google Docs / PHI.
// --------------------------------------------------

return [
  {
    json: {
      schemaVersion: "1.0",

      artifactType:
        "regression-evidence-bundle",

      regressionRunId,

      generatedAt,

      knowledgeFileCount:
        knowledge.length,

      knowledge,

      regression
    }
  }
];

const bundle =
  $json;

if (!bundle.regressionRunId) {
  throw new Error(
    "Missing regressionRunId"
  );
}

const fileName =
  `${bundle.regressionRunId}.json`;

const content =
  JSON.stringify(
    bundle,
    null,
    2
  );

return {
  json: {
    regressionRunId:
      bundle.regressionRunId,

    generatedAt:
      bundle.generatedAt,

    knowledgeFileCount:
      bundle.knowledgeFileCount,

    fileName
  },

  binary: {
    data: {
      data:
        Buffer.from(
          content,
          "utf8"
        ).toString(
          "base64"
        ),

      mimeType:
        "application/json",

      fileName
    }
  }
};
